\label{prop:quantisation}
		Let $\gamma:S^1\rightarrow N$ be an embedded separating\footnote{i.e. $N \setminus \gamma(S^1)$ is disconnected} coupled Dirac-geodesic and assume that a component $N_\gamma$ of $N \setminus \gamma(S^1)$ has compact closure with boundary $\gamma$. Then
		\begin{enumerate}
			\item $	\frac{1}{2\pi}\int_{N_\gamma} K_N\, dA \in (\nu +\mathbb{Z})$ where $K_N$ denotes the Gaussian curvature.
			\item If $K_N \circ \gamma \equiv \kappa \neq 0$ is constant then $$\omega_{\Psi} = \frac{2\pi (k+\nu)}{\kappa \,L[\gamma]}$$ where $k+\nu = \chi(N_\gamma) - \frac{1}{2\pi}\int_{N_\gamma}K_N\, dA$ where $\chi(N_\gamma)$ is the Euler characteristic of $N_\gamma$ and $L[\gamma]$ the length of $\gamma$.
		\end{enumerate}

(Corollary 3 in \cite{ammannquestion})
		Let $(u,\Psi)$ be a Dirac-harmonic map from a closed manifold $(M,g)$. Then either
		\begin{enumerate}
			\item $(u,\Psi)$ is uncoupled or
			\item every open neighbourhood $U\subseteq \mathscr{C}^{\infty}(M,N)$ of $u$ contains an element $u_0\in U$ such that $\dim \ker \slashed D^{u_0} < \dim \ker \slashed D^{u}$.
		\end{enumerate}

Let $(\gamma,\Psi)$ be a coupled periodic Dirac-geodesic in $N$ and let $B$ be a Riemannian manifold.
		\begin{enumerate}
			\item Let $\tilde\gamma:S^1 \rightarrow B$ be a periodic geodesic. Then $\gamma\times \tilde\gamma:S^1 \rightarrow N\times B$ with $\Psi \oplus 0$ is a coupled Dirac-geodesic in $N \times B$.
			\item Let $F:N \rightarrow B$ be a totally geodesic\footnote{$\nabla dF = 0$} isometric embedding. Then $(F\circ \gamma, F_*\Psi)$ is a coupled Dirac-geodesic in $B$.
		\end{enumerate}

\label{prop:product}
		Let $(\gamma,\Psi)$ be a coupled periodic Dirac-geodesics in $N$ and $u:M \rightarrow B$ a harmonic map from a spin manifold $M$. Additionally
		\begin{enumerate}
			\item if $\dim M$ is odd assume the existence of harmonic spinors $\psi_1,\psi_2\in \Gamma(\Sigma M)$ such that $|\psi_1|^2-|\psi_2|^2=1$ and
			\item if $\dim M$ is even assume the existence of a harmonic spinor $\psi = (\psi^+,\psi^-)\in \Gamma(\Sigma^+M \oplus \Sigma^-M)$ such that $|\psi^+|^2-|\psi^-|^2=1$
		\end{enumerate} 
		Then there is a coupled Dirac-harmonic map with underlying map $(\gamma,u):S^1 \times M \rightarrow N \times B$.

Take the induced spin structure on $S^1\times M$. Denote by $S_1 = \mathrm{pr}_1^* \Sigma S^1$ and $S_2 = \mathrm{pr}_2^* \Sigma M$ the pullbacks of the spinor bundles via the canonical projections. By Proposition 5 in \cite{klinker2002spinor} the spinor bundle on the product $S^1\times M$ is
		$$
		S = S'\oplus S'' = \begin{cases}
			S_1 \otimes (S_2^+\oplus S_2^-)& \text{ if } \dim M \text{ is even}\\
			(S_1 \otimes S_2) \oplus (S_1\otimes S_2)& \text{ if } \dim M \text{ is odd}
		\end{cases}
		$$
		where $S_2^+$ and $S_2^-$ in the even case are the even and odd subbundles of $S_2$. The Clifford multiplication along tangent vectors of $S^1$ and $M$ are given by
		$$
		\begin{bmatrix}
			\mathrm{cl}^{S_1}\otimes 1 & 0 \\
			0 & -\mathrm{cl}^{S_1} \otimes 1
		\end{bmatrix} \text{ and }
		\begin{bmatrix}
		0 & 1 \otimes \mathrm{cl}^{S_2} \\
		1 \otimes \mathrm{cl}^{S_2} & 0
		\end{bmatrix}
		$$
		respectively.\footnote{Note, that $S'$ and $S''$ are not the even and odd subbundles of $S$.} This implies that the Dirac operator on $S$ decomposes as well. By
		$$
		S \otimes (\gamma^*TN\oplus u^*TB) \cong \begin{cases}
			S_1 \otimes \gamma^*TN \otimes S_2  \oplus S_1 \otimes S_2\otimes u^*TB & \text{ if } \dim M \text{ is even}\\
			(S_1 \otimes \gamma^*TN \otimes S_2)^{\oplus 2}  \oplus (S_1 \otimes S_2\otimes u^*TB)^{\oplus 2}& \text{ if } \dim M \text{ is odd}
		\end{cases}
		$$
		the twisted spinor is defined as
		$$
		\hat\Psi = \begin{cases}
			\Psi\otimes \psi^+ \oplus \Psi \otimes \psi^- \oplus 0\oplus 0& \text{ if } \dim M \text{ is even}\\
			\Psi\otimes \psi_1 \oplus \Psi\otimes \psi_2 \oplus0 \oplus0& \text{ if } \dim M \text{ is odd}
		\end{cases}.
		$$
		By construction $\slashed D^{(\gamma,u)}\hat \Psi=0$. Let $e_1$ be a unit tangent vector along the $S^1$-factor and $\Psi = \Psi^\alpha\otimes \theta_\alpha$ a local expression for $\Psi$. The curvature term in the odd case is
		\begin{align*}
			\mathcal{R}^{N\times B}((\gamma,u),\hat \Psi) &= \frac{1}{2} \left \langle \Psi^\alpha\otimes \begin{bmatrix}
				\psi_1 \\ \psi_2
			\end{bmatrix} , \mathrm{cl}^{S}_{e_1}\left(\Psi^\beta\otimes \begin{bmatrix}
			\psi_1 \\ \psi_2
			\end{bmatrix} \right) \right \rangle_S R^{N\times B}(\theta_\alpha,\theta_\beta) d(\gamma,u)(e_i)\\
			&= \frac{1}{2} \left \langle \Psi^\alpha, \mathrm{cl}^{S_1}_{e_1}(\Psi^\beta) \right \rangle_{S_1} ( \langle \psi_1,\psi_1 \rangle_{S_2}-\langle \psi_2,\psi_2 \rangle_{S_2}) R^{N}(\theta_\alpha,\theta_\beta) \dot\gamma\\
			& = \mathcal{R}^N(\gamma,\Psi) \oplus 0
		\end{align*}
		and similarly in the even case. By $\Delta (\gamma,u) = (\nabla_{\dot\gamma}\dot \gamma, \Delta u)$ the assertion follows.
